diff -ruN '--exclude=node_modules' '--exclude=.git' a/csv-stream.test.ts b/csv-stream.test.ts
--- a/csv-stream.test.ts	1970-01-01 00:00:00.000000000 +0000
+++ b/csv-stream.test.ts	2026-10-29 13:57:33.134618018 +0000
@@ -0,0 +1,245 @@
+import { expect, test } from "bun:test";
+import { CsvStream, parseCsv } from "./csv";
+
+function feed(chunks: string[]): string[][] {
+  const s = new CsvStream();
+  const rows: string[][] = [];
+  for (const c of chunks) rows.push(...s.push(c));
+  rows.push(...s.end());
+  return rows;
+}
+
+function splitEvery(text: string): string[] {
+  return text.split("");
+}
+
+/** The result of feeding `chunks`: the rows, or the SyntaxError thrown. */
+function outcome(chunks: string[]): string[][] | SyntaxError {
+  try {
+    return feed(chunks);
+  } catch (e) {
+    return e as SyntaxError;
+  }
+}
+
+function expected(text: string): string[][] | SyntaxError {
+  try {
+    return parseCsv(text);
+  } catch (e) {
+    return e as SyntaxError;
+  }
+}
+
+function expectSame(chunks: string[]) {
+  const text = chunks.join("");
+  const want = expected(text);
+  const got = outcome(chunks);
+  if (want instanceof SyntaxError) {
+    expect(got).toBeInstanceOf(SyntaxError);
+    expect((got as SyntaxError).message).toBe(want.message);
+  } else {
+    expect(got).toEqual(want);
+  }
+}
+
+function mulberry32(seed: number) {
+  return () => {
+    seed = (seed + 0x6d2b79f5) | 0;
+    let t = Math.imul(seed ^ (seed >>> 15), 1 | seed);
+    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
+    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
+  };
+}
+
+/** Cuts `text` at random places, and sometimes inserts an empty chunk. */
+function randomSplit(text: string, rand: () => number): string[] {
+  const pieces: string[] = [];
+  let start = 0;
+  for (let i = 1; i < text.length; i++) {
+    if (rand() < 0.5) {
+      pieces.push(text.slice(start, i));
+      start = i;
+    }
+  }
+  pieces.push(text.slice(start));
+  if (rand() < 0.2) pieces.splice(Math.floor(rand() * (pieces.length + 1)), 0, "");
+  return pieces;
+}
+
+test("a stream returns each row once its row end arrives, and the rest at the end", () => {
+  const s = new CsvStream();
+  expect(s.push("a,b\nc,")).toEqual([["a", "b"]]);
+  expect(s.push("d")).toEqual([]);
+  expect(s.end()).toEqual([["c", "d"]]);
+});
+
+test("splitting one character at a time gives the same rows as parseCsv", () => {
+  const text = 'a,b\r\nc\nd,"e,\r\nf""g",\r\n';
+  expect(feed(splitEvery(text))).toEqual(parseCsv(text));
+});
+
+test("a lone \\r belongs to its field, at the end of the input too", () => {
+  expect(feed(["a\rb\n"])).toEqual([["a\rb"]]);
+  expect(feed(["a\r"])).toEqual([["a\r"]]);
+});
+
+test("a \\r at the end of a chunk waits for the next character", () => {
+  const s = new CsvStream();
+  expect(s.push("a\r")).toEqual([]);
+  expect(s.push("\nb")).toEqual([["a"]]);
+  expect(s.end()).toEqual([["b"]]);
+});
+
+test("a quoted field may hold separators, row ends and doubled quotes across chunks", () => {
+  expect(feed(['"x"', '"y"'])).toEqual([['x"y']]);
+  expect(feed(['"a', ",\r", '\n"', '"b"'])).toEqual([['a,\r\n"b']]);
+  expect(feed(['"a"', '"b"'])).toEqual([['a"b']]);
+});
+
+test("a quote at the end of a chunk may still close the field", () => {
+  const s = new CsvStream();
+  expect(s.push('"ab"')).toEqual([]);
+  expect(s.push(",c\n")).toEqual([["ab", "c"]]);
+});
+
+test("after a closing quote only a separator, a row end or the end of input may follow", () => {
+  expect(() => feed(['"a"b'])).toThrow(SyntaxError);
+  expect(() => feed(['"a"\rx'])).toThrow(SyntaxError);
+  expect(() => feed(['"a"\r'])).toThrow(SyntaxError);
+  expect(feed(['"a"\r', "\n"])).toEqual([["a"]]);
+  expect(feed(['"a"', "\r\n"])).toEqual([["a"]]);
+});
+
+test("a quote in an unquoted field is a SyntaxError", () => {
+  const s = new CsvStream();
+  expect(() => s.push('a"')).toThrow(SyntaxError);
+});
+
+test("a quoted field still open at the end is a SyntaxError", () => {
+  const s = new CsvStream();
+  expect(s.push('"ab')).toEqual([]);
+  expect(() => s.end()).toThrow(SyntaxError);
+});
+
+test("a BOM is dropped only at the very start of the input", () => {
+  expect(feed(["", "\uFEFFa"])).toEqual([["a"]]);
+  expect(feed(["\uFEFF"])).toEqual([]);
+  expect(feed(['a\n\uFEFFb'])).toEqual([["a"], ["\uFEFFb"]]);
+});
+
+test("end-of-input rules: empty input, trailing row end, empty line, trailing comma", () => {
+  expect(feed([])).toEqual([]);
+  expect(feed(["", ""])).toEqual([]);
+  expect(feed(["a\n"])).toEqual([["a"]]);
+  expect(feed(["a\n\nb"])).toEqual([["a"], [""], ["b"]]);
+  expect(feed(["a,"])).toEqual([["a", ""]]);
+  expect(feed(["\n"])).toEqual([[""]]);
+});
+
+test("error messages and offsets match parseCsv, whatever the split", () => {
+  for (const text of ['x\n"a"b', 'ab"c', '"open', 'a,"b"\r"', '\uFEFF"a"\rq']) {
+    for (let k = 0; k <= text.length; k++) {
+      expectSame([text.slice(0, k), text.slice(k)]);
+    }
+    expectSame(splitEvery(text));
+  }
+});
+
+test("every string over the alphabet up to length 6 agrees with parseCsv", () => {
+  const alphabet = ["a", ",", '"', "\r", "\n", "\uFEFF"];
+  const rand = mulberry32(1);
+  const strings = [""];
+  let layer = [""];
+  for (let n = 1; n <= 6; n++) {
+    layer = layer.flatMap((s) => alphabet.map((c) => s + c));
+    strings.push(...layer);
+  }
+  for (const text of strings) expectSame(randomSplit(text, rand));
+});
+
+test("every split of random strings up to length 8 agrees with parseCsv", () => {
+  const alphabet = ["a", ",", '"', "\r", "\n"];
+  const rand = mulberry32(2);
+  for (let t = 0; t < 300; t++) {
+    const n = 1 + Math.floor(rand() * 8);
+    let text = "";
+    for (let i = 0; i < n; i++) text += alphabet[Math.floor(rand() * alphabet.length)];
+    for (let mask = 0; mask < 1 << (text.length - 1); mask++) {
+      const chunks: string[] = [];
+      let start = 0;
+      for (let i = 1; i < text.length; i++) {
+        if (mask & (1 << (i - 1))) {
+          chunks.push(text.slice(start, i));
+          start = i;
+        }
+      }
+      chunks.push(text.slice(start));
+      expectSame(chunks);
+    }
+  }
+});
+
+test("random longer strings agree with parseCsv, and complete rows are returned as they arrive", () => {
+  const alphabet = ["a", ",", '"', "\r", "\n", '"', "\n", "\uFEFF"];
+  const rand = mulberry32(3);
+  for (let t = 0; t < 2000; t++) {
+    const n = Math.floor(rand() * 31);
+    let text = "";
+    for (let i = 0; i < n; i++) text += alphabet[Math.floor(rand() * alphabet.length)];
+    const chunks = randomSplit(text, rand);
+    expectSame(chunks);
+
+    const s = new CsvStream();
+    let got: string[][] = [];
+    let prefix = "";
+    for (const c of chunks) {
+      prefix += c;
+      try {
+        got = got.concat(s.push(c));
+      } catch {
+        break;
+      }
+      const want = expected(prefix);
+      if (!(want instanceof SyntaxError) && prefix.endsWith("\n")) expect(got).toEqual(want);
+    }
+  }
+});
+
+test("a very long quoted field and a very long row are handled one character at a time", () => {
+  const long = "x".repeat(200_000);
+  const s = new CsvStream();
+  expect(s.push('"')).toEqual([]);
+  for (const c of long) s.push(c);
+  expect(s.push('"')).toEqual([]);
+  expect(s.push(",")).toEqual([]);
+  expect(s.end()).toEqual([[long, ""]]);
+
+  const row = Array.from({ length: 200_000 }, (_, i) => String(i % 10));
+  const t = new CsvStream();
+  for (const f of row) {
+    expect(t.push(f + ",")).toEqual([]);
+  }
+  expect(t.push("\n")).toEqual([[...row, ""]]);
+  expect(t.end()).toEqual([]);
+});
+
+test("after end, push and end throw", () => {
+  const s = new CsvStream();
+  s.push("a");
+  expect(s.end()).toEqual([["a"]]);
+  expect(() => s.end()).toThrow("CsvStream has ended");
+  expect(() => s.push("b")).toThrow("CsvStream has ended");
+});
+
+test("after a SyntaxError, every later call throws the same error", () => {
+  const s = new CsvStream();
+  let first: unknown;
+  try {
+    s.push('"a"b');
+  } catch (e) {
+    first = e;
+  }
+  expect(first).toBeInstanceOf(SyntaxError);
+  expect(() => s.push("\n")).toThrow(first as SyntaxError);
+  expect(() => s.end()).toThrow(first as SyntaxError);
+});
diff -ruN '--exclude=node_modules' '--exclude=.git' a/csv.ts b/csv.ts
--- a/csv.ts	2026-10-29 13:54:43.063743917 +0000
+++ b/csv.ts	2026-10-29 13:57:12.678616802 +0000
@@ -50,3 +50,124 @@
   rows.push(row);
   return rows;
 }
+
+type State = "fieldStart" | "unquoted" | "quoted" | "quoteInQuoted" | "afterClose" | "crUnquoted" | "crAfterClose";
+
+/** Reads CSV chunk by chunk. The rows from all calls together are the rows `parseCsv` gives for the whole input. */
+export class CsvStream {
+  #offset = 0;
+  #state: State = "fieldStart";
+  #row: string[] = [];
+  #field = "";
+  #rowOpen = false;
+  #crAt = 0;
+  #error?: SyntaxError;
+  #ended = false;
+
+  push(chunk: string): string[][] {
+    this.#check();
+    const rows: string[][] = [];
+    try {
+      for (let k = 0; k < chunk.length; k++) {
+        const at = this.#offset++;
+        if (at === 0 && chunk[k] === "﻿") continue;
+        this.#char(chunk[k]!, at, rows);
+      }
+    } catch (e) {
+      this.#error = e as SyntaxError;
+      throw e;
+    }
+    return rows;
+  }
+
+  end(): string[][] {
+    this.#check();
+    const rows: string[][] = [];
+    try {
+      if (this.#state === "quoted") throw new SyntaxError("a quoted field is still open at the end of the input");
+      if (this.#state === "crAfterClose") throw new SyntaxError(`unexpected "\\r" after a closing quote at offset ${this.#crAt}`);
+      if (this.#state === "crUnquoted") this.#field += "\r";
+      if (this.#rowOpen) {
+        this.#row.push(this.#field);
+        rows.push(this.#row);
+      }
+    } catch (e) {
+      this.#error = e as SyntaxError;
+      throw e;
+    }
+    this.#ended = true;
+    return rows;
+  }
+
+  #check() {
+    if (this.#error) throw this.#error;
+    if (this.#ended) throw new Error("CsvStream has ended");
+  }
+
+  #char(c: string, at: number, rows: string[][]) {
+    this.#rowOpen = true;
+    switch (this.#state) {
+      case "quoted":
+        if (c !== '"') this.#field += c;
+        else this.#state = "quoteInQuoted";
+        return;
+      case "quoteInQuoted":
+        if (c === '"') {
+          this.#field += '"';
+          this.#state = "quoted";
+          return;
+        }
+        this.#state = "afterClose";
+        return this.#char(c, at, rows);
+      case "afterClose":
+        if (c === ",") return this.#comma();
+        if (c === "\n") return this.#rowEnd(rows);
+        if (c === "\r") {
+          this.#state = "crAfterClose";
+          this.#crAt = at;
+          return;
+        }
+        throw new SyntaxError(`unexpected ${JSON.stringify(c)} after a closing quote at offset ${at}`);
+      case "crAfterClose":
+        if (c === "\n") return this.#rowEnd(rows);
+        throw new SyntaxError(`unexpected "\\r" after a closing quote at offset ${this.#crAt}`);
+      case "crUnquoted":
+        if (c === "\n") return this.#rowEnd(rows);
+        this.#field += "\r";
+        this.#state = "unquoted";
+        return this.#char(c, at, rows);
+      case "fieldStart":
+        if (c === '"') {
+          this.#state = "quoted";
+          return;
+        }
+        this.#state = "unquoted";
+        return this.#char(c, at, rows);
+      case "unquoted":
+        if (c === ",") return this.#comma();
+        if (c === "\n") return this.#rowEnd(rows);
+        if (c === "\r") {
+          this.#state = "crUnquoted";
+          return;
+        }
+        if (c === '"') throw new SyntaxError(`a quote in a field that is not quoted, at offset ${at}`);
+        this.#field += c;
+        return;
+    }
+  }
+
+  #comma() {
+    this.#row.push(this.#field);
+    this.#field = "";
+    this.#state = "fieldStart";
+  }
+
+  #rowEnd(rows: string[][]) {
+    this.#row.push(this.#field);
+    rows.push(this.#row);
+    this.#row = [];
+    this.#field = "";
+    this.#state = "fieldStart";
+    this.#rowOpen = false;
+  }
+}

diff -ruN '--exclude=node_modules' '--exclude=.git' a/csv-stream.test.ts b/csv-stream.test.ts
--- a/csv-stream.test.ts	1970-01-01 00:00:00.000000000 +0000
+++ b/csv-stream.test.ts	2026-10-29 13:56:25.254613983 +0000
@@ -0,0 +1,168 @@
+import { expect, test } from "bun:test";
+import { CsvStream, parseCsv } from "./csv";
+
+function streamParse(chunks: string[]): string[][] {
+  const s = new CsvStream();
+  const rows: string[][] = [];
+  for (const chunk of chunks) rows.push(...s.push(chunk));
+  rows.push(...s.end());
+  return rows;
+}
+
+// Whole input, every one-cut and two-cut split, one character per chunk, and seeded random splits with empty chunks.
+function splitsOf(text: string): string[][] {
+  const out: string[][] = [[text], [...text]];
+  for (let cut = 0; cut <= text.length; cut++) out.push([text.slice(0, cut), text.slice(cut)]);
+  let seed = 1;
+  const rand = () => {
+    seed = (Math.imul(seed, 1103515245) + 12345) >>> 0;
+    return seed / 2 ** 32;
+  };
+  for (let k = 0; k < 30; k++) {
+    const parts: string[] = [];
+    for (let i = 0; i < text.length; ) {
+      const n = 1 + Math.floor(rand() * 4);
+      parts.push(text.slice(i, i + n));
+      i += n;
+      if (rand() < 0.2) parts.push("");
+    }
+    out.push(parts);
+  }
+  return out;
+}
+
+function expectSameAsParseCsv(text: string) {
+  let expected: string[][] | undefined;
+  let expectedMessage: string | undefined;
+  try {
+    expected = parseCsv(text);
+  } catch (e) {
+    expect(e).toBeInstanceOf(SyntaxError);
+    expectedMessage = (e as Error).message;
+  }
+  for (const chunks of splitsOf(text)) {
+    if (expectedMessage === undefined) {
+      expect(streamParse(chunks)).toEqual(expected!);
+    } else {
+      let error: unknown;
+      try {
+        streamParse(chunks);
+      } catch (e) {
+        error = e;
+      }
+      expect(error).toBeInstanceOf(SyntaxError);
+      expect((error as Error).message).toBe(expectedMessage);
+    }
+  }
+}
+
+const inputs = [
+  "",
+  "\n",
+  "\r\n",
+  "\r",
+  "a",
+  "a\n",
+  "a\n\nb",
+  "a,",
+  ",,\n",
+  "a,b\r\n\"x,\"\"y\"\"\",z\n",
+  "a\r",
+  "a\rb\n",
+  "a\r\r\nb",
+  "a\r,b",
+  "\"a\rb\nc,d\"\r\n",
+  "\"a\"\"b\"",
+  "\"\"\n",
+  "\"\"\"x\"\"\"",
+  "\"a\"\r\n\"b\"\r\n",
+  "\"a\"\n",
+  "\uFEFFa,b\n",
+  "\uFEFF",
+  "\uFEFF\uFEFF",
+  "\uFEFF\n",
+  "a\uFEFF,b",
+  "é,😀\n\"😀\"x",
+];
+
+const badInputs = [
+  'x"',
+  'a"b',
+  '"a"b',
+  '"a"\r',
+  '"a"\rb',
+  '"a"\r,',
+  '"a',
+  '"a""',
+  'a\r"b',
+];
+
+test("every split of each valid input gives the rows parseCsv gives", () => {
+  for (const text of inputs) expectSameAsParseCsv(text);
+});
+
+test("every split of each invalid input throws the SyntaxError parseCsv throws", () => {
+  for (const text of badInputs) expectSameAsParseCsv(text);
+});
+
+test("a row is returned in the call where its row end arrives", () => {
+  const s = new CsvStream();
+  expect(s.push("a\n")).toEqual([["a"]]);
+  expect(s.push("b\r")).toEqual([]);
+  expect(s.push("\n")).toEqual([["b"]]);
+  expect(s.push('"x"')).toEqual([]);
+  expect(s.push("\n")).toEqual([["x"]]);
+  expect(s.end()).toEqual([]);
+});
+
+test("a lone carriage return is field text, also at a chunk end and at the input end", () => {
+  expect(streamParse(["a\r", "b\n"])).toEqual([["a\rb"]]);
+  expect(streamParse(["a\r"])).toEqual([["a\r"]]);
+});
+
+test("a doubled quote split across chunks is one quote", () => {
+  expect(streamParse(['"a"', '"b"'])).toEqual([['a"b']]);
+  expect(streamParse(['"a"', ',b'])).toEqual([["a", "b"]]);
+});
+
+test("a BOM is dropped only at the very start of the input", () => {
+  expect(streamParse(["", "\uFEFFa"])).toEqual([["a"]]);
+  expect(streamParse(["\uFEFF", "\uFEFF"])).toEqual([["\uFEFF"]]);
+  expect(streamParse(["\uFEFF"])).toEqual([]);
+});
+
+test("a row end just before the input ends does not start another row", () => {
+  expect(streamParse(["a\n"])).toEqual([["a"]]);
+  expect(streamParse([])).toEqual([]);
+  expect(streamParse(["a,"])).toEqual([["a", ""]]);
+});
+
+test("a stream that failed or ended refuses more input", () => {
+  const failed = new CsvStream();
+  expect(() => failed.push('"a"b')).toThrow(SyntaxError);
+  expect(() => failed.push("c\n")).toThrow(Error);
+  expect(() => failed.end()).toThrow(Error);
+
+  const ended = new CsvStream();
+  ended.push("a\n");
+  expect(ended.end()).toEqual([]);
+  expect(() => ended.push("b")).toThrow(Error);
+  expect(() => ended.end()).toThrow(Error);
+});
+
+test("a quoted field still open at the end throws from end", () => {
+  const s = new CsvStream();
+  s.push('a,"b');
+  expect(() => s.end()).toThrow(SyntaxError);
+});
+
+test("long input in one-character chunks stays fast and exact", () => {
+  const text = "a,b\n".repeat(50000) + '"' + "x".repeat(100000) + '",y\n';
+  const s = new CsvStream();
+  const rows: string[][] = [];
+  for (const c of text) rows.push(...s.push(c));
+  rows.push(...s.end());
+  expect(rows.length).toBe(50001);
+  expect(rows[50000]).toEqual(["x".repeat(100000), "y"]);
+  expect(rows.slice(0, 50000).every((r) => r[0] === "a" && r[1] === "b")).toBe(true);
+});
diff -ruN '--exclude=node_modules' '--exclude=.git' a/csv.ts b/csv.ts
--- a/csv.ts	2026-10-29 13:54:43.071292987 +0000
+++ b/csv.ts	2026-10-29 13:56:04.022612721 +0000
@@ -50,3 +50,124 @@
   rows.push(row);
   return rows;
 }
+
+type State = "fieldStart" | "unquoted" | "quoted" | "quoteSeen" | "afterClose" | "crPending" | "crAfterClose";
+
+/**
+ * Reads the same CSV as `parseCsv`, one chunk at a time. Each `push` returns the rows whose row end has arrived, and
+ * `end` returns the rest once the input is over. The rows from all the calls together equal `parseCsv` of the whole
+ * input, and what `parseCsv` rejects makes a call throw the same SyntaxError. Work per character is constant.
+ */
+export class CsvStream {
+  private row: string[] = [];
+  private field = "";
+  private state: State = "fieldStart";
+  private pos = 0;
+  private crAt = 0;
+  private rowOpen = false;
+  private closed = false;
+
+  push(chunk: string): string[][] {
+    this.assertOpen();
+    const rows: string[][] = [];
+    for (let k = 0; k < chunk.length; k++) {
+      const c = chunk[k]!;
+      if (this.pos === 0 && c === "﻿") {
+        this.pos++;
+        continue;
+      }
+      this.feed(c, rows);
+      this.pos++;
+    }
+    return rows;
+  }
+
+  end(): string[][] {
+    this.assertOpen();
+    this.closed = true;
+    const rows: string[][] = [];
+    if (!this.rowOpen) return rows;
+    if (this.state === "quoted") throw new SyntaxError("a quoted field is still open at the end of the input");
+    if (this.state === "crAfterClose") throw new SyntaxError(`unexpected "\\r" after a closing quote at offset ${this.crAt}`);
+    if (this.state === "crPending") this.field += "\r";
+    this.endRow(rows);
+    return rows;
+  }
+
+  private assertOpen() {
+    if (this.closed) throw new Error("CsvStream has already ended or failed");
+  }
+
+  private fail(message: string): never {
+    this.closed = true;
+    throw new SyntaxError(message);
+  }
+
+  private endField() {
+    this.row.push(this.field);
+    this.field = "";
+    this.state = "fieldStart";
+  }
+
+  private endRow(rows: string[][]) {
+    this.endField();
+    rows.push(this.row);
+    this.row = [];
+    this.rowOpen = false;
+  }
+
+  private feed(c: string, rows: string[][]) {
+    this.rowOpen = true;
+    if (this.state === "fieldStart") {
+      if (c === '"') {
+        this.state = "quoted";
+        return;
+      }
+      this.state = "unquoted";
+    }
+    switch (this.state) {
+      case "unquoted":
+        if (c === ",") this.endField();
+        else if (c === "\n") this.endRow(rows);
+        else if (c === "\r") {
+          this.state = "crPending";
+          this.crAt = this.pos;
+        } else if (c === '"') this.fail(`a quote in a field that is not quoted, at offset ${this.pos}`);
+        else this.field += c;
+        break;
+      case "crPending":
+        if (c === "\n") this.endRow(rows);
+        else {
+          this.field += "\r";
+          this.state = "unquoted";
+          this.feed(c, rows);
+        }
+        break;
+      case "quoted":
+        if (c === '"') this.state = "quoteSeen";
+        else this.field += c;
+        break;
+      case "quoteSeen":
+        if (c === '"') {
+          this.field += '"';
+          this.state = "quoted";
+        } else {
+          this.state = "afterClose";
+          this.feed(c, rows);
+        }
+        break;
+      case "afterClose":
+        if (c === ",") this.endField();
+        else if (c === "\n") this.endRow(rows);
+        else if (c === "\r") {
+          this.state = "crAfterClose";
+          this.crAt = this.pos;
+        } else this.fail(`unexpected ${JSON.stringify(c)} after a closing quote at offset ${this.pos}`);
+        break;
+      case "crAfterClose":
+        if (c === "\n") this.endRow(rows);
+        else this.fail(`unexpected "\\r" after a closing quote at offset ${this.crAt}`);
+        break;
+    }
+  }
+}

