+    event = undefined;
+    data = [];
+    return msg;
+  };
+  const handle = (line: string): SseMessage | undefined => {
+    if (line === '') return take();
+    if (line[0] === ':') return;
+    const colon = line.indexOf(':');
+    const field = colon < 0 ? line : line.slice(0, colon);
+    let value = colon < 0 ? '' : line.slice(colon + 1);
+    if (value[0] === ' ') value = value.slice(1);
+    if (field === 'event') event = value;
+    else if (field === 'data') data.push(value);
+  };
+  let open = true;
+  try {
+    for (;;) {
+      const { done, value } = await reader.read().catch((e) => {
+        open = false;
+        throw e;
+      });
+      if (done) {
+        open = false;
+        break;
+      }
+      buf += dec.decode(value, { stream: true });
+      let nl: number;
+      while ((nl = buf.indexOf('\n')) >= 0) {
+        const line = buf.slice(0, nl).replace(/\r$/, '');
+        buf = buf.slice(nl + 1);
+        const msg = handle(line);
+        if (msg) yield msg;
+      }
+    }
+    buf += dec.decode();
+    if (buf) {
+      const msg = handle(buf.replace(/\r$/, ''));
+      if (msg) yield msg;
+    }
+    const msg = take();
+    if (msg) yield msg;
+  } finally {
+    if (open) await reader.cancel();
+    reader.releaseLock();
+  }
 }

