+  let vCounter = 0;
+
+  for (let step = 0; step < 2000; step++) {
+    const op = rand(4);
+    const key = rand(6);
+    let got: unknown;
+    let want: unknown;
+    if (op === 0) {
+      const v = vCounter++;
+      cache.set(key, v);
