+        mEvict(e, 'delete');
+        want = true;
+      } else if (e) {
+        mEvict(e, 'expired');
+        want = false;
+      } else {
+        want = false;
+      }
+    } else {
+      t += rand(401);
+      got = null;
+      want = null;
+    }
+    const liveKeys = model.filter(mLive).map((e) => e.k).reverse();
+    expect({ step, got, keys: cache.keys(), size: cache.size, log: [...log] }).toEqual({
+      step,
+      got: want,
+      keys: liveKeys,
+      size: liveKeys.length,
+      log: [...mLog],
+    });
+  }
